from solution import freq_element


def test_issue_example_from_description():
    """Example: freq_element([[1,2,3,2],[4,5,6,2],[7,1,9,5]]) equals {2:3,1:2,5:2,...}."""
    result = freq_element([[1, 2, 3, 2], [4, 5, 6, 2], [7, 1, 9, 5]])
    # counts: 2->1+1+1=3, 1->1+1=2, 5->1+1=2, 3,4,6,7,9->1 each
    assert result == {2: 3, 1: 2, 5: 2, 3: 1, 4: 1, 6: 1, 7: 1, 9: 1}


def test_issue_empty_outer_list():
    """Find frequency of the elements in a given list of lists with empty input."""
    result = freq_element([])
    # total elements: 0, so sum of counts = 0
    assert result == {}


def test_issue_empty_inner_lists():
    """Find frequency of the elements in a given list of lists with empty rows."""
    result = freq_element([[], []])
    # total elements: 0+0=0, so no keys
    assert result == {}


def test_issue_single_element():
    """Find frequency of the elements in a given list of lists with one element."""
    result = freq_element([[5]])
    # counts: 5->1
    assert result == {5: 1}


def test_issue_repeated_within_single_sublist():
    """Find frequency of the elements in a given list of lists counting repeats in one row."""
    result = freq_element([[1, 1, 1]])
    # counts: 1->1+1+1=3
    assert result == {1: 3}


def test_issue_duplicates_across_sublists():
    """Find frequency of the elements in a given list of lists across rows."""
    result = freq_element([[1, 2], [2, 3], [2, 1]])
    # counts: 1->1+1=2, 2->1+1+1=3, 3->1
    assert result == {1: 2, 2: 3, 3: 1}


def test_issue_negative_and_zero_values():
    """Find frequency of the elements in a given list of lists including 0 and negatives."""
    result = freq_element([[0, -1, 0], [-1, -1, 2]])
    # counts: 0->1+1=2, -1->1+1+1=3, 2->1
    assert result == {0: 2, -1: 3, 2: 1}


def test_issue_large_repeated_count():
    """Find frequency of the elements in a given list of lists with many duplicates."""
    result = freq_element([[7, 7, 7, 7, 7], [7, 7, 7], [8]])
    # counts: 7->5+3=8, 8->1
    assert result == {7: 8, 8: 1}


def test_contract_returns_dict():
    """Function returns frequency mapping as a dict."""
    result = freq_element([[1, 2], [2, 3]])
    # counts: 1->1, 2->1+1=2, 3->1
    expected = {1: 1, 2: 2, 3: 1}
    assert isinstance(result, dict)
    assert result == expected


def test_contract_does_not_mutate_input():
    """Function finds frequency without changing the given list of lists."""
    nums = [[1, 2, 2], [3, 1]]
    snapshot = [[1, 2, 2], [3, 1]]
    result = freq_element(nums)
    # counts: 1->1+1=2, 2->1+1=2, 3->1
    assert result == {1: 2, 2: 2, 3: 1}
    assert nums == snapshot


def test_contract_counts_sum_to_total():
    """Frequency values sum to the total number of elements in the list of lists."""
    nums = [[4, 4, 5], [5, 6]]
    result = freq_element(nums)
    # counts: 4->1+1=2, 5->1+1=2, 6->1; total 3+2=5 and 2+2+1=5
    assert result == {4: 2, 5: 2, 6: 1}
    assert sum(result.values()) == 5
